class RandomRotation90:
    """Rotate by a random multiple of 90 degrees.

    The transform stays inside the orbit of the discrete rotation group, so it
    preserves the geometric invariants expected by downstream rotation-aware
    layers. No shear, scaling, cropping, or continuous-angle affine distortion
    is introduced.
    """

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        if not torch.is_tensor(x):
            raise TypeError("RandomRotation90 expects a torch.Tensor input")
        k = int(torch.randint(0, 4, (1,)).item())
        if k == 0:
            return x
        return torch.rot90(x, k, dims=(-2, -1))


class FunctorialDataset:
    def __init__(self):
        # Use only group-actions that commute with the preserved symmetry:
        # rotations by 0, 90, 180, or 270 degrees.
        self.transform = transforms.Compose([
            RandomRotation90(),
        ])

    def augment(self, x: torch.Tensor) -> torch.Tensor:
        # Applying the functorial, symmetry-preserving transform.
        return self.transform(x)

