class RandomRotation90(torch.nn.Module):
    """Rotate by a uniformly random multiple of 90 degrees.

    This keeps the augmentation inside the orbit of the discrete rotation group
    (the cyclic group C4 acting on the last two tensor axes), so the transform
    is a functor with respect to 90-degree rotational symmetry: composing the
    augmentation with any 90-degree rotation yields another valid augmentation.
    """

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        k = int(torch.randint(0, 4, (1,)).item())
        return torch.rot90(x, k, dims=(-2, -1))


class FunctorialDataset:
    def __init__(self):
        # Only symmetry-preserving augmentations: the input is mapped to another
        # element of the same group orbit (rotations by multiples of 90 degrees
        # plus mirror reflections), so no shear, resampling distortion or
        # translation is introduced.
        self.transform = transforms.Compose([
            RandomRotation90(),
            transforms.RandomHorizontalFlip(),
        ])

    def augment(self, x: torch.Tensor) -> torch.Tensor:
        # Applying the functorial, symmetry-preserving transforms
        return self.transform(x)

