def _identity(x: torch.Tensor) -> torch.Tensor:
    return x


def _rot90(k):
    """Rotate a (..., H, W) tensor by k * 90 degrees counter-clockwise."""

    def f(x: torch.Tensor) -> torch.Tensor:
        return torch.rot90(x, k, dims=(-2, -1))

    return f


