            transforms.RandomChoice([
                transforms.Lambda(_identity),
                transforms.Lambda(_rot90(1)),
                transforms.Lambda(_rot90(2)),
                transforms.Lambda(_rot90(3)),
            ]),
        ])

    def augment(self, x: torch.Tensor) -> torch.Tensor:
        # Applying only group actions from the discrete rotation group C4.
        return self.transform(x)

