import torch
import torchvision.transforms as transforms


class RandomRotation90:
    """Rotate by a random multiple of 90 degrees.

    Rotating by k * 90 degrees maps the square grid onto itself, so this is a
    symmetry of the underlying pixel lattice (an element of the dihedral group
    of the square) rather than a distortion of it.
    """

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        if not torch.is_tensor(x):
            return x
        k = int(torch.randint(0, 4, (1,)).item())
        if k:
            x = torch.rot90(x, k, dims=(-2, -1))
        return x

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}()"


class SymmetricAugmenter:
    def __init__(self):
        # Only use augmentations that are symmetries of the square lattice:
        # reflections (flips) and rotations by multiples of 90 degrees.  These
        # generate the dihedral group D4, so the augmentation acts as a functor
        # on the orbit of any 90-degree rotation and commutes with it instead
        # of shearing/cropping the grid apart.
        self.transform = transforms.Compose([
            transforms.RandomHorizontalFlip(),
            transforms.RandomVerticalFlip(),
            RandomRotation90(),
        ])

    def augment(self, x: torch.Tensor) -> torch.Tensor:
        return self.transform(x)
